-- 0001_baseline (SQLite): the schema a fresh AnixOps Control created before
-- the migration runner (go_dev 4eb87485, release 4.2.1): the tables and
-- indexes of the application models, the kernel models and the startup
-- schema steps, in the order that start created them, flux tables included
-- (they go with the forwarding cleanup). The kernel API views are not part
-- of it: packagestore creates them at every start.
--
-- Recorded once from that start on an empty database (legacy_oracle_test.go)
-- and never edited: every database records this file's checksum
-- (docs/reference/database-migrations.md).
CREATE TABLE `v4_forward_legacy_archive` (`id` integer PRIMARY KEY AUTOINCREMENT,`path` text NOT NULL,`sha256` text NOT NULL,`size_bytes` integer,`schema` text NOT NULL,`trigger` text NOT NULL,`actor` text,`row_counts` text,`created_at` datetime);
CREATE TABLE `v4_forward_legacy_node` (`id` integer PRIMARY KEY AUTOINCREMENT,`node_id` integer NOT NULL,`node_ref` text NOT NULL,`node_name` text,`state` text NOT NULL,`checks` text,`detail` text,`checked_at` datetime,`abandoned_at` datetime,`abandoned_by` text,`abandon_reason` text,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `v4_forward_legacy_drop` (`id` integer PRIMARY KEY AUTOINCREMENT,`archive_id` integer,`archive_path` text,`archive_sha256` text,`backup` text,`dropped` text,`already_missing` text,`actor` text,`created_at` datetime);
CREATE TABLE `v2_plan` (`id` integer PRIMARY KEY AUTOINCREMENT,`group_id` integer,`transfer_enable` integer,`speed_limit` integer,`device_limit` integer,`name` text,`content` text,`show` integer DEFAULT 0,`sort` integer,`renew` integer DEFAULT 1,`reset_price` integer,`reset_traffic_method` integer,`capacity_limit` integer,`month_price` integer,`quarter_price` integer,`half_year_price` integer,`year_price` integer,`two_year_price` integer,`three_year_price` integer,`onetime_price` integer,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `v2_user` (`id` integer PRIMARY KEY AUTOINCREMENT,`invite_user_id` integer,`telegram_id` integer,`email` text,`password` text,`password_algo` text,`password_salt` text,`balance` integer DEFAULT 0,`discount` integer,`commission_type` integer DEFAULT 0,`commission_rate` integer,`commission_balance` integer DEFAULT 0,`token` text,`uuid` text,`device_limit` integer,`speed_limit` integer,`flow_reset_time` integer DEFAULT 0,`transfer_enable` integer DEFAULT 0,`u` integer DEFAULT 0,`d` integer DEFAULT 0,`plan_id` integer,`group_id` integer,`expired_at` integer,`banned` integer DEFAULT 0,`remark_content` text,`is_admin` integer DEFAULT 0,`is_staff` integer DEFAULT 0,`last_login_at` integer,`created_at` datetime,`updated_at` datetime,CONSTRAINT `fk_v2_user_plan` FOREIGN KEY (`plan_id`) REFERENCES `v2_plan`(`id`));
CREATE TABLE `v2_order` (`id` integer PRIMARY KEY AUTOINCREMENT,`invite_user_id` integer,`user_id` integer,`plan_id` integer,`coupon_id` integer,`payment_id` integer,`type` integer,`period` text,`trade_no` text,`callback_no` text,`total_amount` integer,`discount_amount` integer,`surplus_amount` integer,`refund_amount` integer,`balance` integer,`surplus_order` text,`status` integer DEFAULT 0,`commission_status` integer DEFAULT 0,`commission_balance` integer DEFAULT 0,`paid_at` integer,`created_at` datetime,`updated_at` datetime,CONSTRAINT `fk_v2_order_plan` FOREIGN KEY (`plan_id`) REFERENCES `v2_plan`(`id`),CONSTRAINT `fk_v2_order_user` FOREIGN KEY (`user_id`) REFERENCES `v2_user`(`id`));
CREATE TABLE `v2_payment` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text,`icon` text,`method` text,`provider` text,`config` text,`notify` text,`sort` integer DEFAULT 0,`enable` integer DEFAULT 1,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `v2_payment_log` (`id` integer PRIMARY KEY AUTOINCREMENT,`order_id` integer,`payment_id` integer,`trade_no` text,`callback_no` text,`method` text,`provider` text,`amount` integer,`currency` text,`status` integer DEFAULT 0,`raw_data` text,`tx_hash` text,`wallet_address` text,`network` text,`created_at` datetime,`updated_at` datetime);
