CREATE TABLE `v2_node_protocol` (`id` integer PRIMARY KEY AUTOINCREMENT,`node_id` integer,`name` text,`type` text,`port` integer,`enable` integer DEFAULT 1,`show` integer DEFAULT 1,`sort` integer DEFAULT 0,`group_id` integer,`host` text,`tls` integer DEFAULT 0,`alpn` text,`settings` text,`tls_settings` text,`transport` text,`transport_settings` text,`reality_settings` text,`custom_config` text,`created_at` datetime,`updated_at` datetime,CONSTRAINT `fk_v2_node_protocols` FOREIGN KEY (`node_id`) REFERENCES `v2_node`(`id`));
